constraints:
1 ≤ N ≤ 10^{5}
1 ≤ K ≤ N
0 ≤ arr[i] ≤ 10^{7}

expected time complexity: O(N)
expected auxiliary space: O(k)

standard_solution_code:
class Solution:

	def max_of_subarrays(self, arr, n, k):
		ans = []
		Q = deque([])
		for i in range(n):
			if Q and Q[0] <= i - k:
				Q.popleft()
			while Q and arr[Q[-1]] <= arr[i]:
				Q.pop()
			Q.append(i)
			if i >= k - 1:
				ans.append(arr[Q[0]])
		return ans
